/* Resources content — transcribed from "AltiusNxt Website Content – Page by Page" (PDF pages 1–26).
   Copy is kept exactly as published, including its typos and repeated sentences.
   Section block types: heading, paragraph, bullets, numbered, table, quote, banner-text.
   List items are either a string or { label, text, items? } (rendered "<b>label:</b> text").
   To use a real image later, each item's `image` is an imported thumbnail from src/assets/resources; remove it to fall back to the placeholder. */

const lead = (label, text, items) => (items ? { label, text, items } : { label, text })
const h2 = (text) => ({ type: 'heading', level: 2, text })
const h3 = (text) => ({ type: 'heading', level: 3, text })
const p = (text) => ({ type: 'paragraph', text })
const em = (text) => ({ type: 'paragraph', text, emphasis: true })
const ul = (items) => ({ type: 'bullets', items })
const ol = (items) => ({ type: 'numbered', items })
const table = (rows) => ({ type: 'table', rows })
const quote = (text, author, role) => ({ type: 'quote', text, author, role })
const banner = (text) => ({ type: 'banner-text', text })

